FUNCTION_BLOCK FB_P03
VAR_INPUT
    Value : REAL;
    hiLevel : REAL;
    loLevel : REAL;
    hystWindow : REAL;
END_VAR
VAR_OUTPUT
    hiAlarm : BOOL;
    loAlarm : BOOL;
    error : BOOL;
    status : WORD;
END_VAR
VAR
    initCount : INT := 0;       (* 用于前两个周期保持初态，满足 C10 G[0,1] *)
    lastError : BOOL := FALSE;  (* 上一周期是否发生参数错误，用于 C1 错误后下一周期强制关断 *)
END_VAR

(* 上电前两个周期保持初态：无报警、无错误、status = 0 (C10) *)
IF initCount < 2 THEN
    error := FALSE;
    status := 16#0000;
    hiAlarm := FALSE;
    loAlarm := FALSE;
    initCount := initCount + 1;
    RETURN;
END_IF;

(* K1: 若 loLevel >= hiLevel，立即报错并退出，同时强制关断报警 *)
IF loLevel >= hiLevel THEN
    error := TRUE;
    status := 16#8001;
    hiAlarm := FALSE;
    loAlarm := FALSE;
    lastError := TRUE;
    RETURN;
END_IF;

(* K2: 若 hystWindow >= (hiLevel - loLevel)，报错并退出，同时强制关断报警 *)
IF hystWindow >= (hiLevel - loLevel) THEN
    error := TRUE;
    status := 16#8002;
    hiAlarm := FALSE;
    loAlarm := FALSE;
    lastError := TRUE;
    RETURN;
END_IF;

(* 参数合法。若上一周期存在错误，则本周期必须保持报警关断 (C1)，并清除错误状态 *)
IF lastError THEN
    error := FALSE;
    status := 16#0000;
    hiAlarm := FALSE;
    loAlarm := FALSE;
    lastError := FALSE;
    RETURN;
END_IF;

(* 正常报警逻辑 *)
error := FALSE;
status := 16#0000;

(* K3: 高报滞回 *)
IF Value > hiLevel THEN
    hiAlarm := TRUE;
ELSIF Value < (hiLevel - hystWindow) THEN
    hiAlarm := FALSE;
END_IF;

(* K4: 低报滞回 *)
IF Value < loLevel THEN
    loAlarm := TRUE;
ELSIF Value > (loLevel + hystWindow) THEN
    loAlarm := FALSE;
END_IF;

END_FUNCTION_BLOCK
